//! Who holds the heap, for `horizon-ctl memory` (feature `alloc-census`, for
//! measuring only): mimalloc with a tag in front of each block, and the live
//! bytes of each tag. A block's tag is what ran on its thread when it was
//! allocated: the innermost [`tag`] (a startup step, a timed span or a pool
//! job: `startup::time`, `spans::time` and `jobs` set them), else the
//! thread's name. A block keeps its tag when another thread frees or grows
//! it, so a column generated by a pool job and kept by the server thread
//! counts for the job.
//!
//! Each block costs a header of 16 bytes (its alignment when larger) and an
//! atomic add: heaptrack's interpreter needed more than 7 GB for the game
//! (18 GB with line tables), this needs nothing beside it.
use std::{
    alloc::{GlobalAlloc, Layout},
    cell::Cell,
    sync::atomic::{AtomicIsize, AtomicPtr, AtomicUsize, Ordering::Relaxed},
};

const TAGS: usize = 512;
/// Blocks allocated while this thread names itself, and past the table's end.
const UNTAGGED: u32 = 0;
const NONE: u32 = u32::MAX;

static LIVE: [AtomicIsize; TAGS] = [const { AtomicIsize::new(0) }; TAGS];
static NAME_PTR: [AtomicPtr<u8>; TAGS] = [const { AtomicPtr::new(std::ptr::null_mut()) }; TAGS];
static NAME_LEN: [AtomicUsize; TAGS] = [const { AtomicUsize::new(0) }; TAGS];
/// The next free slot; slot 0 is [`UNTAGGED`].
static NEXT: AtomicUsize = AtomicUsize::new(1);

thread_local! {
    static STEP: Cell<u32> = const { Cell::new(NONE) };
    static THREAD: Cell<u32> = const { Cell::new(NONE) };
    /// Allocations this thread made before its tag settled: std names a
    /// thread after its first few, so the name is read again until then.
    static NAMING: Cell<u32> = const { Cell::new(0) };
    static BUSY: Cell<bool> = const { Cell::new(false) };
}

/// The slot of `name`, registering it. A race may give one name two slots;
/// [`census`] adds them up.
fn slot(name: &'static str) -> u32 {
    let n = NEXT.load(Relaxed).min(TAGS);
    for i in 1..n {
        let ptr = NAME_PTR[i].load(Relaxed);
        if !ptr.is_null() && NAME_LEN[i].load(Relaxed) == name.len() {
            // SAFETY: the slot holds a leaked or static string of that length.
            let s = unsafe { std::slice::from_raw_parts(ptr, name.len()) };
            if s == name.as_bytes() {
                return i as u32;
            }
        }
    }
    let i = NEXT.fetch_add(1, Relaxed);
    if i >= TAGS {
        return UNTAGGED;
    }
    NAME_LEN[i].store(name.len(), Relaxed);
    NAME_PTR[i].store(name.as_ptr().cast_mut(), Relaxed);
    i as u32
}

/// The OS name of the calling thread, read without allocating.
#[cfg(any(target_vendor = "apple", target_os = "linux"))]
fn thread_name(buf: &mut [u8; 64]) -> &[u8] {
    // SAFETY: writes at most `buf.len()` bytes, NUL included, into `buf`.
    let ok = unsafe {
        libc::pthread_getname_np(libc::pthread_self(), buf.as_mut_ptr().cast(), buf.len())
    } == 0;
    let len = buf.iter().position(|&b| b == 0).unwrap_or(0);
    if ok { &buf[..len] } else { &[] }
}
#[cfg(not(any(target_vendor = "apple", target_os = "linux")))]
fn thread_name(_: &mut [u8; 64]) -> &[u8] {
    &[]
}

/// The calling thread's own tag: its name, looked up again for its first
/// allocations. Allocations made while it registers a name are untagged.
fn thread_tag() -> u32 {
    let known = THREAD.get();
    if known != NONE && NAMING.get() >= 256 {
        return known;
    }
    if BUSY.replace(true) {
        return UNTAGGED;
    }
    NAMING.set(NAMING.get().saturating_add(1));
    let mut buf = [0u8; 64];
    let name = match std::str::from_utf8(thread_name(&mut buf)) {
        Ok("") | Err(_) => "unnamed thread",
        Ok(name) => name,
    };
    let tag = if known != NONE && slot_name(known) == Some(name) {
        known
    } else {
        // Thread names are few: each is leaked once.
        let name: &'static str = match name {
            "unnamed thread" => "unnamed thread",
            name => Box::leak(name.to_owned().into_boxed_str()),
        };
        slot(name)
    };
    THREAD.set(tag);
    BUSY.set(false);
    tag
}

fn slot_name(i: u32) -> Option<&'static str> {
    let i = i as usize;
    let ptr = NAME_PTR.get(i)?.load(Relaxed);
    if ptr.is_null() {
        return None;
    }
    // SAFETY: registered slots hold leaked or static UTF-8 of that length.
    Some(unsafe {
        std::str::from_utf8_unchecked(std::slice::from_raw_parts(ptr, NAME_LEN[i].load(Relaxed)))
    })
}

fn current() -> u32 {
    match STEP.get() {
        NONE => thread_tag(),
        step => step,
    }
}

/// While it lives, the calling thread's blocks are tagged `name`.
pub struct Tag(u32);
impl Drop for Tag {
    fn drop(&mut self) {
        STEP.set(self.0);
    }
}
/// Tag the calling thread's blocks `name` until the guard drops.
pub fn tag(name: &'static str) -> Tag {
    let previous = STEP.get();
    let was = BUSY.replace(true);
    let tag = slot(name);
    BUSY.set(was);
    STEP.set(tag);
    Tag(previous)
}

/// Live bytes by tag, largest first.
pub fn census() -> Vec<(&'static str, isize)> {
    let mut by_name: Vec<(&'static str, isize)> = Vec::new();
    for i in 0..NEXT.load(Relaxed).min(TAGS) {
        let bytes = LIVE[i].load(Relaxed);
        let name = slot_name(i as u32).unwrap_or("untagged");
        match by_name.iter_mut().find(|(n, _)| *n == name) {
            Some(entry) => entry.1 += bytes,
            None => by_name.push((name, bytes)),
        }
    }
    by_name.sort_by_key(|(_, bytes)| std::cmp::Reverse(*bytes));
    by_name
}

/// mimalloc with a tag in front of each block (see the module).
pub struct CensusAllocator;

/// The header in front of a block of `layout`: 16 bytes, or its alignment.
fn header(layout: Layout) -> usize {
    layout.align().max(16)
}

// SAFETY: forwards every call to mimalloc with the header added; the tag sits
// in the header's last four bytes, inside the block mimalloc returned.
unsafe impl GlobalAlloc for CensusAllocator {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        let h = header(layout);
        let Ok(outer) = Layout::from_size_align(layout.size() + h, layout.align().max(16)) else {
            return std::ptr::null_mut();
        };
        // SAFETY: `outer` has a nonzero size.
        let base = unsafe { mimalloc::MiMalloc.alloc(outer) };
        if base.is_null() {
            return base;
        }
        let tag = current();
        LIVE[tag as usize].fetch_add(layout.size() as isize, Relaxed);
        // SAFETY: `h` bytes precede the caller's block inside the allocation.
        unsafe {
            let block = base.add(h);
            block.sub(4).cast::<u32>().write_unaligned(tag);
            block
        }
    }
    unsafe fn dealloc(&self, block: *mut u8, layout: Layout) {
        let h = header(layout);
        // SAFETY: `block` came from `alloc` with this layout.
        unsafe {
            let tag = block.sub(4).cast::<u32>().read_unaligned();
            LIVE[tag as usize].fetch_sub(layout.size() as isize, Relaxed);
            let outer =
                Layout::from_size_align_unchecked(layout.size() + h, layout.align().max(16));
            mimalloc::MiMalloc.dealloc(block.sub(h), outer);
        }
    }
    unsafe fn realloc(&self, block: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
        let h = header(layout);
        // SAFETY: `block` came from `alloc` with this layout; the header moves with it.
        unsafe {
            let outer =
                Layout::from_size_align_unchecked(layout.size() + h, layout.align().max(16));
            let tag = block.sub(4).cast::<u32>().read_unaligned();
            let base = mimalloc::MiMalloc.realloc(block.sub(h), outer, new_size + h);
            if base.is_null() {
                return base;
            }
            LIVE[tag as usize].fetch_add(new_size as isize - layout.size() as isize, Relaxed);
            base.add(h)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{CensusAllocator, census, tag};
    use std::alloc::{GlobalAlloc, Layout};

    fn live(name: &str) -> isize {
        census().iter().find(|(n, _)| *n == name).map_or(0, |e| e.1)
    }

    #[test]
    fn a_block_counts_for_its_step_until_another_thread_frees_it() {
        let layout = Layout::from_size_align(1 << 20, 64).unwrap();
        let block = {
            let _tag = tag("test.step");
            // SAFETY: a nonzero layout.
            unsafe { CensusAllocator.alloc(layout) }
        };
        assert_eq!(live("test.step"), 1 << 20);
        // SAFETY: `block` came from this allocator with `layout`.
        let block = unsafe { CensusAllocator.realloc(block, layout, 3 << 20) } as usize;
        assert_eq!(live("test.step"), 3 << 20, "growing keeps the step's tag");
        let grown = Layout::from_size_align(3 << 20, 64).unwrap();
        std::thread::spawn(move || {
            let _other = tag("test.other");
            // SAFETY: `block` came from this allocator with `grown`.
            unsafe { CensusAllocator.dealloc(block as *mut u8, grown) };
        })
        .join()
        .unwrap();
        assert_eq!(live("test.step"), 0);
        assert_eq!(live("test.other"), 0);
    }

    #[test]
    fn without_a_step_a_block_counts_for_its_thread() {
        let layout = Layout::from_size_align(4096, 8).unwrap();
        let (name, block) = std::thread::Builder::new()
            .name("census-test".into())
            .spawn(move || {
                // SAFETY: a nonzero layout.
                let block = unsafe { CensusAllocator.alloc(layout) } as usize;
                (std::thread::current().name().unwrap().to_owned(), block)
            })
            .unwrap()
            .join()
            .unwrap();
        // Linux keeps 15 bytes of a thread's name; the test's is shorter.
        assert_eq!(live(&name), 4096);
        // SAFETY: `block` came from this allocator with `layout`.
        unsafe { CensusAllocator.dealloc(block as *mut u8, layout) };
        assert_eq!(live(&name), 0);
    }
}
